//── Optional cycle counter probe ──────────────────────────────────────────────
// The E2E Corstone builds pre-include the CMSIS device header (ARMCM55.h /
// ARMCM4_FP.h), so DWT and the debug control block are visible here when the
// target exposes a cycle counter. We time only model_run() inside the
// iteration loop so the metric stays focused on dispatch + kernel execution
// rather than init or output verification.
//
// CMSIS 6 deprecates the CMSIS 5 ``CoreDebug`` spelling in favour of ``DCB``:
// 6.0.0 omitted it, while 6.1.0+ retains it as a deprecated alias. Prefer
// ``DCB`` and fall back to ``CoreDebug`` for compatible CMSIS layouts.
#if defined(DCB) && defined(DCB_DEMCR_TRCENA_Msk)
#define HKV_SEGMENTATION_TEST_DEMCR       (DCB->DEMCR)
#define HKV_SEGMENTATION_TEST_DEMCR_TRCENA DCB_DEMCR_TRCENA_Msk
#elif defined(CoreDebug) && defined(CoreDebug_DEMCR_TRCENA_Msk)
#define HKV_SEGMENTATION_TEST_DEMCR       (CoreDebug->DEMCR)
#define HKV_SEGMENTATION_TEST_DEMCR_TRCENA CoreDebug_DEMCR_TRCENA_Msk
#endif

typedef enum {
    hkv_segmentation_test_counter_unavailable = 0,
    hkv_segmentation_test_counter_pmu,
    hkv_segmentation_test_counter_dwt,
    hkv_segmentation_test_counter_systick,
} hkv_segmentation_test_counter_kind_t;

static hkv_segmentation_test_counter_kind_t hkv_segmentation_test_counter_kind = hkv_segmentation_test_counter_unavailable;

static void hkv_segmentation_test_cycle_counter_probe_spin(void)
{
    for (volatile uint32_t i = 0; i < 64U; ++i) {
#if defined(__NOP)
        __NOP();
#endif
    }
}

static int hkv_segmentation_test_cycle_counter_enable(void)
{
#if defined(__PMU_PRESENT) && (__PMU_PRESENT == 1U)
    uint32_t pmu_start = 0;
    uint32_t pmu_end = 0;
    ARM_PMU_Disable();
    ARM_PMU_CYCCNT_Reset();
    ARM_PMU_Enable();
    ARM_PMU_CNTR_Enable(PMU_CNTENSET_CCNTR_ENABLE_Msk);
    pmu_start = ARM_PMU_Get_CCNTR();
    hkv_segmentation_test_cycle_counter_probe_spin();
    pmu_end = ARM_PMU_Get_CCNTR();
    if (((PMU->CNTENSET & PMU_CNTENSET_CCNTR_ENABLE_Msk) != 0U) && (pmu_end != pmu_start)) {
        hkv_segmentation_test_counter_kind = hkv_segmentation_test_counter_pmu;
        return 1;
    }
#elif defined(DWT) && defined(DWT_CTRL_CYCCNTENA_Msk) && defined(HKV_SEGMENTATION_TEST_DEMCR)
    uint32_t dwt_start = 0;
    uint32_t dwt_end = 0;
    HKV_SEGMENTATION_TEST_DEMCR |= HKV_SEGMENTATION_TEST_DEMCR_TRCENA;
    DWT->CYCCNT = 0;
    DWT->CTRL |= DWT_CTRL_CYCCNTENA_Msk;
    dwt_start = DWT->CYCCNT;
    hkv_segmentation_test_cycle_counter_probe_spin();
    dwt_end = DWT->CYCCNT;
    if (((DWT->CTRL & DWT_CTRL_CYCCNTENA_Msk) != 0U) && (dwt_end != dwt_start)) {
        hkv_segmentation_test_counter_kind = hkv_segmentation_test_counter_dwt;
        return 1;
    }
#endif

#if defined(SysTick) && defined(SysTick_LOAD_RELOAD_Msk) && defined(SysTick_CTRL_ENABLE_Msk) && defined(SysTick_CTRL_CLKSOURCE_Msk)
    uint32_t systick_start = 0;
    uint32_t systick_end = 0;
    SysTick->CTRL = 0;
    SysTick->LOAD = SysTick_LOAD_RELOAD_Msk;
    SysTick->VAL = 0;
    SysTick->CTRL = SysTick_CTRL_ENABLE_Msk | SysTick_CTRL_CLKSOURCE_Msk;
    systick_start = SysTick_LOAD_RELOAD_Msk - SysTick->VAL;
    hkv_segmentation_test_cycle_counter_probe_spin();
    systick_end = SysTick_LOAD_RELOAD_Msk - SysTick->VAL;
    if (systick_end != systick_start) {
        hkv_segmentation_test_counter_kind = hkv_segmentation_test_counter_systick;
        return 1;
    }
#endif

    hkv_segmentation_test_counter_kind = hkv_segmentation_test_counter_unavailable;
    return 0;
}

static uint32_t hkv_segmentation_test_cycle_counter_read(void)
{
    switch (hkv_segmentation_test_counter_kind) {
        case hkv_segmentation_test_counter_pmu:
#if defined(__PMU_PRESENT) && (__PMU_PRESENT == 1U)
            return ARM_PMU_Get_CCNTR();
#else
            return 0;
#endif
        case hkv_segmentation_test_counter_dwt:
#if defined(DWT) && defined(DWT_CTRL_CYCCNTENA_Msk)
            return DWT->CYCCNT;
#else
            return 0;
#endif
        case hkv_segmentation_test_counter_systick:
#if defined(SysTick) && defined(SysTick_LOAD_RELOAD_Msk)
            return SysTick_LOAD_RELOAD_Msk - SysTick->VAL;
#else
            return 0;
#endif
        default:
            return 0;
    }
}

static uint32_t hkv_segmentation_test_cycle_counter_delta(uint32_t start, uint32_t end)
{
    if (hkv_segmentation_test_counter_kind == hkv_segmentation_test_counter_systick) {
#if defined(SysTick_LOAD_RELOAD_Msk)
        const uint32_t modulo = SysTick_LOAD_RELOAD_Msk + 1U;
        return (end >= start) ? (end - start) : (modulo - start + end);
#else
        return 0;
#endif
    }
    return (uint32_t)(end - start);
}


