//── Callback ──────────────────────────────────────────────────────────────────
static void hkv_segmentation_test_stimulus_callback(
    int32_t op,
    hkv_segmentation_operator_state_t state,
    int32_t status,
    void *user_data
) {
    (void)user_data;
    if (state == hkv_segmentation_op_state_init_finished) {
        HKV_SEGMENTATION_PRINTF("Operator %ld init finished with status %ld\n", (long)op, (long)status);
    }
    if (state == hkv_segmentation_op_state_run_finished) {
        HKV_SEGMENTATION_PRINTF("Operator %ld run finished with status %ld\n", (long)op, (long)status);
    }
}


//── Context ───────────────────────────────────────────────────────────────────
static hkv_segmentation_model_context_t hkv_segmentation_test_stimulus_context = {
    .callback = hkv_segmentation_test_stimulus_callback,
    .user_data = NULL
};


int32_t
hkv_segmentation_test_case_init(void)
{
    // Initialize model
    int32_t status = hkv_segmentation_model_init(
        &hkv_segmentation_test_stimulus_context
    );
    if (status != 0) {
        return status;
    }
    return 0;
}

int32_t
hkv_segmentation_test_case_run(void)
{
    int32_t result = 0;
    const int num_iterations = 1;
    const int have_cycle_counter = hkv_segmentation_test_cycle_counter_enable();
    void (*saved_callback)(int32_t, hkv_segmentation_operator_state_t, int32_t, void *) = hkv_segmentation_test_stimulus_context.callback;
    uint64_t model_run_cycles_total = 0;

    if (have_cycle_counter) {
        hkv_segmentation_test_stimulus_context.callback = NULL;
    }

    // Run the model N times on the same stimulus
    for (int iter = 0; iter < num_iterations; iter++) {
        uint32_t cycle_start = 0;
        uint32_t cycle_end = 0;

        // Copy input tensors to context (before each iteration to ensure input persists)
    arm_memcpy_s8(
        hkv_segmentation_test_stimulus_context.inputs[0].data,
        (int8_t *)hkv_segmentation_test_stimulus_input_0,
        256
    );

        if (have_cycle_counter) {
            cycle_start = hkv_segmentation_test_cycle_counter_read();
        }
        result = hkv_segmentation_model_run(&hkv_segmentation_test_stimulus_context);
        if (have_cycle_counter) {
            cycle_end = hkv_segmentation_test_cycle_counter_read();
            model_run_cycles_total += hkv_segmentation_test_cycle_counter_delta(cycle_start, cycle_end);
        }
        if (result != 0) {
            HKV_SEGMENTATION_PRINTF("Model run failed with status %ld (iteration %d)\n", (long)result, iter);
            hkv_segmentation_test_stimulus_context.callback = saved_callback;
            return result;
        }
    }

    if (have_cycle_counter) {
        const uint64_t cycles_per_iter = (num_iterations > 0)
            ? (model_run_cycles_total / (uint64_t)num_iterations)
            : 0;
        HKV_SEGMENTATION_PRINTF(
            "HELIA_E2E_METRIC counter=%s model_run_cycles_total=%llu model_run_cycles_per_iter=%llu iterations=%d\n",
            hkv_segmentation_test_counter_kind == hkv_segmentation_test_counter_pmu ? "pmu" :
            (hkv_segmentation_test_counter_kind == hkv_segmentation_test_counter_dwt ? "dwt" : "systick"),
            (unsigned long long)model_run_cycles_total,
            (unsigned long long)cycles_per_iter,
            num_iterations
        );
    } else {
        HKV_SEGMENTATION_PRINTF("HELIA_E2E_METRIC model_run_cycles_unavailable=1 iterations=%d\n", num_iterations);
    }

    hkv_segmentation_test_stimulus_context.callback = saved_callback;

    // Verify outputs once after all iterations
    int8_t *act_0 = (int8_t *)hkv_segmentation_test_stimulus_context.outputs[0].data;
    int8_t *exp_0 = (int8_t *)hkv_segmentation_test_stimulus_golden_0;
    for (int i = 0; i < 1024; i++) {
        int act = (int)act_0[i];
        int exp = (int)exp_0[i];
        int diff = abs(act - exp);
        if (diff > (int)1.0) {
            HKV_SEGMENTATION_PRINTF("Output mismatch at index [%d][%d]: expected %d, got %d (diff=%d)\n", 0, i, exp, act, diff);
            result = 1;
        }
    }

    // Check for errors
    if (result == 0) {
        HKV_SEGMENTATION_PRINTF("Test passed!\n");
    } else {
        HKV_SEGMENTATION_PRINTF("Test failed!\n");
    }
    return result;

}